cat > /home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out-4/play/users/u076/system/state/workspace/programs/task-54c9fb29.py <<'PY'
def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # Recolor outside the 1-shape's bounding box (exterior expansion) with 2;
    # within the bounding box, enclosed zero cavities become 3.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    if not pts: return out
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    # 2 colors the one-cell frame immediately outside shape bbox, where blank
    # cells exist, matching the demo's left/right/bottom and top row portions.
    for r in range(max(0,r0-1), min(h,r1+2)):
        for c in range(max(0,c0-1), min(w,c1+2)):
            if r<r0 or r>r1 or c<c0 or c>c1:
                if grid[r][c]==0: out[r][c]=2
    # Identify 0 components within bounding box; enclosed means not touching box edge.
    seen=set()
    for r in range(r0,r1+1):
      for c in range(c0,c1+1):
        if grid[r][c]!=0 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]; edge=False
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          if y in (r0,r1) or x in (c0,c1): edge=True
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if r0<=yy<=r1 and c0<=xx<=c1 and grid[yy][xx]==0 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        if not edge:
          for y,x in comp: out[y][x]=3
    return out
